    t[33836] = { name = "Самоцвіт Душі Екзарха", fen = "It's hard to believe that this bauble holds the spirits of many victims. Nevertheless, you can sense them in turmoil within.", fua = "Важко повірити, що ця дрібничка тримає душі багатьох жертв. І все ж ви відчуваєте, як вони бентежаться всередині." }
    t[33839] = { name = "Рагу з Калірі", fen = "Looks like revenge is on the menu tonight!  Kaliri never tasted so good.", fua = "Схоже, сьогодні в меню помста! Калірі ще ніколи не була такою смачною." }
    t[33840] = { name = "Шепіт Мурмура", fen = "The professor was right, Murmur's 'whisper' does have a physical manifestation!", fua = "Професор мав рацію: «шепіт» Мурмура справді має фізичний прояв!" }
    t[33847] = { name = "Голова Мисливця Епох", fen = "It'll look fine mounted just so long as the wind trader's customer has plenty of wall space.", fua = "Як трофей вона матиме чудовий вигляд, аби тільки в покупця торгівця вітрами вистачило місця на стіні." }
    t[33848] = { name = "Смажений Демон-сюрприз", fen = "Smells delicious!", fua = "Пахне розкішно!" }
    t[33849] = "Манова Ягода"
    t[33850] = { name = "Духовна Юшка", fen = "It's not made of chicken, but it's definitely good for the soul.", fua = "Вона не з курки, але точно добра для душі." }
    t[33853] = "Перстень Панування Месника"
    t[33858] = { name = "Пісковий Годинник Еонуса", fen = "The sands are falling upward!", fua = "Пісок сиплеться вгору!" }
    t[33859] = { name = "Живець Спотворного Скалкодрева", fen = "Hard to believe that the druids think they can regrow such a massive ancient from such a small twig.", fua = "Важко повірити, що друїди вважають, ніби можуть виростити такого величезного древня з такої малої гілочки." }
    t[33860] = { name = "Проєктор Патейлеона", fen = "So this is what he used to appear all over the place!", fua = "Тож ось чим він користувався, щоб з'являтися всюди!" }
    t[33861] = { name = "Сувій Скайрісса", fen = "Indeed, the language written upon the scroll is illegible. In fact, it hurts your brain to even look upon it!", fua = "Справді, мова, якою написаний сувій, нечитабельна. Ба більше, навіть дивитися на неї боляче для голови!" }
    t[33869] = { name = "Рецепт: Смажений Кривавоплавник", fen = "Teaches you how to cook Broiled Bloodfin.", fua = "Навчає вас готувати Смаженого Кривавоплавника." }
    t[33870] = { name = "Рецепт: Юшка з Черепориби", fen = "Teaches you how to cook Skullfish Soup.", fua = "Навчає вас готувати Юшку з Черепориби." }
    t[33871] = { name = "Рецепт: Грозові Котлети", fen = "Teaches you how to cook Stormchops.", fua = "Навчає вас готувати Грозові Котлети." }
